//! The frozen, built-in repository state.
//!
//! There is no repository on disk: `gitlike` only ever shows these three
//! commits and two branches.

use serde::Serialize;

#[derive(Clone, Copy, Serialize)]
pub struct Commit {
    pub hash: &'static str,
    pub author: &'static str,
    pub message: &'static str,
}

#[derive(Clone, Copy, Serialize)]
pub struct Branch {
    pub name: &'static str,
    pub hash: &'static str,
}

/// Newest first.
pub const COMMITS: [Commit; 3] = [
    Commit {
        hash: "a3f4",
        author: "alice",
        message: "Fix off-by-one",
    },
    Commit {
        hash: "b7e2",
        author: "bob",
        message: "Add parser",
    },
    Commit {
        hash: "c1a9",
        author: "alice",
        message: "Initial import",
    },
];

/// Sorted by ref name, which is the order `ref-list` prints.
pub const BRANCHES: [Branch; 2] = [
    Branch {
        name: "dev",
        hash: "b7e2",
    },
    Branch {
        name: "main",
        hash: "a3f4",
    },
];

/// The checked-out branch.
pub const CURRENT_BRANCH: &str = "main";

/// The commits `log` shows, newest first, capped by `limit` when there is one.
pub fn log(limit: Option<u64>) -> Vec<Commit> {
    let count = match limit {
        Some(limit) => (limit as usize).min(COMMITS.len()),
        None => COMMITS.len(),
    };
    COMMITS[..count].to_vec()
}

pub fn find(hash: &str) -> Option<Commit> {
    COMMITS.iter().copied().find(|commit| commit.hash == hash)
}

pub fn head() -> Commit {
    let hash = BRANCHES
        .iter()
        .find(|branch| branch.name == CURRENT_BRANCH)
        .expect("the current branch exists")
        .hash;
    find(hash).expect("the current branch points at a known commit")
}

