//! Configuration: two keys, four sources.
//!
//! Highest precedence first: command-line flags (applied by the handlers),
//! the nearest `.gitlike.toml` walking up from the working directory, the
//! user config file, then the built-in defaults (both keys unset).

use std::path::{Path, PathBuf};

const REPO_FILE: &str = ".gitlike.toml";

#[derive(Debug, Default, Clone)]
pub struct Config {
    pub log_limit: Option<u64>,
    pub user_name: Option<String>,
}

impl Config {
    /// Resolve the file-backed sources. Flags are layered on top by callers.
    pub fn load() -> Self {
        let repo = nearest_repo_file().and_then(|path| read_table(&path));
        let user = user_config_path().and_then(|path| read_table(&path));

        let mut config = Config::default();
        for table in [repo.as_ref(), user.as_ref()].into_iter().flatten() {
            if config.log_limit.is_none() {
                config.log_limit = lookup(table, "log", "limit")
                    .and_then(|value| value.as_integer())
                    .filter(|limit| *limit > 0)
                    .map(|limit| limit as u64);
            }
            if config.user_name.is_none() {
                config.user_name = lookup(table, "user", "name")
                    .and_then(|value| value.as_str())
                    .map(str::to_string);
            }
        }
        config
    }

    /// The effective value of a key, as `config get` prints it.
    pub fn get(&self, key: &str) -> Option<String> {
        match key {
            "log.limit" => self.log_limit.map(|limit| limit.to_string()),
            "user.name" => self.user_name.clone(),
            _ => None,
        }
    }
}

/// The first `.gitlike.toml` walking up from the working directory. Files
/// further up are not merged, so the search stops at the first hit.
fn nearest_repo_file() -> Option<PathBuf> {
    let mut dir = std::env::current_dir().ok()?;
    loop {
        let candidate = dir.join(REPO_FILE);
        if candidate.is_file() {
            return Some(candidate);
        }
        if !dir.pop() {
            return None;
        }
    }
}

fn user_config_path() -> Option<PathBuf> {
    if let Some(home) = non_empty_var("GITLIKE_CONFIG_HOME") {
        return Some(PathBuf::from(home).join("config.toml"));
    }
    let home = non_empty_var("HOME")?;
    Some(
        PathBuf::from(home)
            .join(".config")
            .join("gitlike")
            .join("config.toml"),
    )
}

fn non_empty_var(name: &str) -> Option<String> {
    std::env::var(name).ok().filter(|value| !value.is_empty())
}

fn read_table(path: &Path) -> Option<toml::Table> {
    let text = std::fs::read_to_string(path).ok()?;
    text.parse::<toml::Table>().ok()
}

/// `log.limit` and `[log] limit` normalize to the same nested lookup.
fn lookup<'a>(table: &'a toml::Table, section: &str, key: &str) -> Option<&'a toml::Value> {
    table.get(section)?.as_table()?.get(key)
}

