//! The command-line surface.
//!
//! Porcelain (`log`, `status`) goes through the dispatch derive, a template
//! and the active theme. Plumbing (`ref-list`, `cat-object`, `config get`)
//! is registered as passthrough in `main`, so no theme, no `--output` mode
//! and no pager can reach its bytes.

use clap::{Parser, Subcommand};
use standout::cli::Dispatch;

#[derive(Parser)]
#[command(name = "gitlike", about = "A tiny version-control inspector")]
pub struct Cli {
    /// Do not page output for this invocation.
    #[arg(long, global = true)]
    pub no_pager: bool,

    #[command(subcommand)]
    pub command: Commands,
}

#[derive(Subcommand, Dispatch)]
#[dispatch(handlers = crate::handlers)]
pub enum Commands {
    /// Show the commit log, newest first.
    #[dispatch(pure)]
    Log {
        /// Show at most N commits, overriding any configured `log.limit`.
        #[arg(long, value_name = "N", value_parser = clap::value_parser!(u64).range(1..))]
        limit: Option<u64>,
    },

    /// Show the current branch and HEAD.
    #[dispatch(pure)]
    Status,

    /// List every ref, sorted by ref name.
    #[dispatch(skip)]
    RefList,

    /// Print the object body for a hash.
    #[dispatch(skip)]
    CatObject {
        /// The object hash.
        hash: String,
    },

    /// Inspect configuration.
    #[dispatch(skip)]
    Config {
        #[command(subcommand)]
        command: ConfigCommands,
    },
}

#[derive(Subcommand)]
pub enum ConfigCommands {
    /// Print the effective value of a key.
    Get {
        /// The configuration key, such as `log.limit`.
        key: String,
    },
}

/// The commands whose output is porcelain: styled, and paged when the
/// destination is an attended terminal.
pub fn is_porcelain(command: Option<&str>) -> bool {
    matches!(command, Some("log") | Some("status"))
}

