//! Plumbing handlers.
//!
//! Registered as passthrough commands: they write their own bytes, so no
//! theme, `--output` mode, terminal detection or pager sits between them and
//! stdout. That is what makes the bytes a stability contract.

use std::io::Write;

use anyhow::Context;
use clap::ArgMatches;
use standout::cli::{AppFailure, CommandContext};

use crate::config::Config;
use crate::repo;

/// Exit status for a hash no object answers to.
const NO_SUCH_OBJECT: u8 = 3;
/// Exit status for `config get` on a key with no effective value.
const UNSET_KEY: u8 = 1;

pub fn ref_list(_matches: &ArgMatches, _ctx: &CommandContext) -> Result<(), anyhow::Error> {
    let mut out = String::new();
    for branch in repo::BRANCHES.iter() {
        out.push_str(&format!("{} refs/heads/{}\n", branch.hash, branch.name));
    }
    write_stdout(&out)
}

pub fn cat_object(matches: &ArgMatches, _ctx: &CommandContext) -> Result<(), anyhow::Error> {
    let hash: &String = matches
        .get_one("hash")
        .context("cat-object requires a hash")?;

    let Some(commit) = repo::find(hash) else {
        return Err(AppFailure::new(
            NO_SUCH_OBJECT,
            format!("gitlike: no such object: {hash}\n"),
        )?
        .into());
    };

    write_stdout(&format!(
        "author {}\nmessage {}\n",
        commit.author, commit.message
    ))
}

pub fn config_get(matches: &ArgMatches, ctx: &CommandContext) -> Result<(), anyhow::Error> {
    let key: &String = matches.get_one("key").context("config get requires a key")?;
    let config = ctx.app_state.get_required::<Config>()?;

    let Some(value) = config.get(key) else {
        // Nothing on either stream, status 1.
        return Err(AppFailure::new(UNSET_KEY, "")?.into());
    };

    write_stdout(&format!("{value}\n"))
}

fn write_stdout(text: &str) -> Result<(), anyhow::Error> {
    let stdout = std::io::stdout();
    let mut handle = stdout.lock();
    handle.write_all(text.as_bytes())?;
    handle.flush()?;
    Ok(())
}

