mod cli;
mod config;
mod handlers;
mod pager;
mod plumbing;
mod repo;

use clap::CommandFactory;
use standout::cli::{App, Dispatch, DispatchResult, HelpResult};
use standout::{embed_styles, embed_templates, InputSources, TargetProperties};

use crate::cli::{Cli, Commands};

/// `GITLIKE_THEME` selects a built-in theme; anything unrecognized is the
/// default one. Themes affect porcelain only.
fn theme_name() -> &'static str {
    match std::env::var("GITLIKE_THEME").as_deref() {
        Ok("mono") => "mono",
        _ => "default",
    }
}

fn main() {
    let mut app = App::builder()
        .app_state(config::Config::load())
        .templates(embed_templates!("src/templates"))
        .styles(embed_styles!("src/styles"))
        .default_theme(theme_name())
        .commands(Commands::dispatch_config())
        .expect("porcelain commands register")
        .command_passthrough("ref-list", plumbing::ref_list)
        .expect("ref-list registers")
        .command_passthrough("cat-object", plumbing::cat_object)
        .expect("cat-object registers")
        .command_passthrough("config.get", plumbing::config_get)
        .expect("config get registers")
        .build()
        .expect("the app is configured");

    // Paging is decided before dispatch: only porcelain pages, and only when
    // the invocation did not opt out.
    let plan = pager::plan(&app);

    let result = app.run_with(
        Cli::command(),
        std::env::args(),
        TargetProperties::detect(),
        InputSources::from_process(),
    );

    let status = exit_code(&result);
    match result.into_outcome() {
        DispatchResult::Handled(output) => {
            let text = output.as_str();
            // Passthrough commands wrote their own bytes already; the
            // framework resolves them to an empty string.
            if !text.is_empty() {
                plan.write(text);
            }
        }
        DispatchResult::Error(error) => write_diagnostic(error.as_str()),
        _ => {}
    }

    std::process::exit(status);
}

/// The framework decides the status; this only unwraps it. A run with no
/// status of its own (a no-match handoff, which this app never produces)
/// counts as success.
fn exit_code(result: &standout::cli::CompletedRun) -> i32 {
    result
        .exit_status()
        .map(|status| i32::from(status.code()))
        .unwrap_or(0)
}

/// `AppFailure` payloads are verbatim, and clap's usage errors carry their
/// own formatting, so the diagnostic is written as it stands — with one
/// trailing newline, and nothing at all when it is empty.
fn write_diagnostic(text: &str) {
    use std::io::Write;

    if text.is_empty() {
        return;
    }
    let stderr = std::io::stderr();
    let mut handle = stderr.lock();
    let _ = handle.write_all(text.as_bytes());
    if !text.ends_with('\n') {
        let _ = handle.write_all(b"\n");
    }
    let _ = handle.flush();
}

/// Silences the unused-import warning for the derive's trait in builds where
/// nothing else names it.
#[allow(dead_code)]
fn _dispatch_is_used<T: Dispatch>() {}

