import os, pty, sys, subprocess

def run(args, env=None):
    e = dict(os.environ)
    if env:
        e.update(env)
    master, slave = pty.openpty()
    p = subprocess.Popen(args, stdout=slave, stderr=subprocess.PIPE, env=e)
    os.close(slave)
    out = b""
    while True:
        try:
            chunk = os.read(master, 4096)
        except OSError:
            break
        if not chunk:
            break
        out += chunk
    p.wait()
    err = p.stderr.read()
    return p.returncode, out, err

if __name__ == "__main__":
    label = sys.argv[1]
    env = {}
    for kv in sys.argv[2].split(",") if sys.argv[2] else []:
        if kv:
            k, v = kv.split("=", 1)
            env[k] = v
    code, out, err = run(sys.argv[3:], env)
    print(f"--- {label}: exit={code}")
    print(f"stdout={out!r}")
    print(f"stderr={err!r}")

