//! Paging.
//!
//! Porcelain pages when stdout is an attended terminal and a pager is
//! configured. Plumbing never reaches this module: it writes its own bytes
//! during dispatch.

use std::io::{IsTerminal, Write};
use std::process::{Command, Stdio};

use clap::CommandFactory;
use standout::cli::{App, HelpResult};
use standout::InputSources;

use crate::cli::{self, Cli};

/// Where a porcelain command's rendered text goes.
pub struct Plan {
    pager: Option<String>,
}

impl Plan {
    /// Write the rendered text plus the one trailing newline the process
    /// edge owns, through the pager when there is one.
    pub fn write(&self, text: &str) {
        if let Some(command) = self.pager.as_deref() {
            if page_through(command, text).is_ok() {
                return;
            }
            // A pager that could not be launched must not cost the user
            // their output.
        }
        let stdout = std::io::stdout();
        let mut handle = stdout.lock();
        let _ = writeln!(handle, "{text}");
        let _ = handle.flush();
    }
}

/// Decide paging before dispatch, from the same parse the run will perform.
pub fn plan(app: &App) -> Plan {
    Plan {
        pager: wants_paging(app).then(pager_command).flatten(),
    }
}

fn wants_paging(app: &App) -> bool {
    if !std::io::stdout().is_terminal() {
        return false;
    }

    let sources = InputSources::from_process();
    match app.get_matches_from(Cli::command(), std::env::args(), &sources) {
        HelpResult::Matches(matches) => {
            !matches.get_flag("no_pager") && cli::is_porcelain(matches.subcommand_name())
        }
        // Help, usage errors and version displays are not porcelain output.
        _ => false,
    }
}

/// `GITLIKE_PAGER`, else `PAGER`; with neither set, output is not paged.
fn pager_command() -> Option<String> {
    for name in ["GITLIKE_PAGER", "PAGER"] {
        if let Ok(value) = std::env::var(name) {
            if !value.trim().is_empty() {
                return Some(value);
            }
        }
    }
    None
}

fn page_through(command: &str, text: &str) -> std::io::Result<()> {
    let mut child = Command::new("sh")
        .arg("-c")
        .arg(command)
        .stdin(Stdio::piped())
        .spawn()?;

    if let Some(mut stdin) = child.stdin.take() {
        // A pager that quits early closes the pipe; that is not a failure.
        let _ = writeln!(stdin, "{text}");
    }
    let _ = child.wait();
    Ok(())
}

