/// `GITLIKE_PAGER`, else `PAGER`; with neither set, output is not paged.
/// A variable that is set but blank names no command, so it pages nothing
/// rather than deferring to the next one.
fn pager_command() -> Option<String> {
    let command = match std::env::var("GITLIKE_PAGER") {
        Ok(value) => value,
        Err(_) => std::env::var("PAGER").ok()?,
    };
    (!command.trim().is_empty()).then_some(command)
}

